function arcThrough(a,m,b){let d=2*(a.x*(m.y-b.y)+m.x*(b.y-a.y)+b.x*(a.y-m.y));let scale=Math.max(Math.hypot(m.x-a.x,m.y-a.y),Math.hypot(b.x-a.x,b.y-a.y),1);if(Math.abs(d)<1e-10*scale*scale)return null;let aa=a.x*a.x+a.y*a.y,mm=m.x*m.x+m.y*m.y,bb=b.x*b.x+b.y*b.y,c={x:(aa*(m.y-b.y)+mm*(b.y-a.y)+bb*(a.y-m.y))/d,y:(aa*(b.x-m.x)+mm*(a.x-b.x)+bb*(m.x-a.x))/d},r=Math.hypot(a.x-c.x,a.y-c.y),deg=q=>Math.atan2(q.y-c.y,q.x-c.x)*180/Math.PI,n=x=>(x%360+360)%360,sa=deg(a),ma=deg(m),ea=deg(b),ccw=n(ma-sa)<=n(ea-sa);return {type:'arc',a:c,b:{x:c.x+r,y:c.y},startAngle:ccw?sa:ea,endAngle:ccw?ea:sa,layer:activeLayer}}
function makePolyline(points,closed=false){let data=MachinaPolyline.create(points,closed),first=data.vertices[0],last=data.vertices.at(-1);return {type:'polyline',a:{x:first.x,y:first.y},b:{x:last.x,y:last.y},...data,layer:activeLayer}}
function appendPolylinePoint(p){if(!editable({layer:activeLayer})){$('#status').textContent='현재 레이어가 잠겨 있거나 숨겨져 있습니다';return}if(polylineDraft.length>=10000){$('#status').textContent='폴리라인 정점 제한에 도달했습니다';return}let prev=polylineDraft.at(-1);if(prev&&Math.hypot(p.x-prev.x,p.y-prev.y)<1e-9)return;polylineDraft.push({x:p.x,y:p.y,bulge:0});start={...p};clearNumeric();$('#status').textContent='정점 '+polylineDraft.length+'개 · 다음 점, Enter 완료, C 닫기';preview=null;render()}
function finishPolyline(closed=false){if(polylineDraft.length<(closed?3:2)){$('#status').textContent=closed?'닫힌 폴리라인은 세 정점 이상 필요합니다':'폴리라인은 두 정점 이상 필요합니다';return}let path=makePolyline(polylineDraft,closed);checkpoint();objects.push(path);setTool('polyline');$('#status').textContent=closed?'닫힌 폴리라인을 만들었습니다':'폴리라인을 만들었습니다'}
function makeSpline(points){let data=MachinaSpline.controlSpline(points),a=MachinaSpline.point(data,data.knots[data.degree]),b=MachinaSpline.point(data,data.knots[data.points.length]);return {type:'spline',a,b,...data,layer:activeLayer}}
function appendSplinePoint(p){if(!editable({layer:activeLayer})){$('#status').textContent='현재 레이어가 잠겨 있거나 숨겨져 있습니다';return}if(splineDraft.length>=1024){$('#status').textContent='스플라인 제어점은 1024개까지 지원합니다';return}let prev=splineDraft.at(-1);if(prev&&Math.hypot(p.x-prev.x,p.y-prev.y)<1e-9)return;splineDraft.push({...p});start={...p};clearNumeric();$('#status').textContent='제어점 '+splineDraft.length+'개 · 다음 점 또는 Enter';preview=null;render()}
function finishSpline(){if(splineDraft.length<2){$('#status').textContent='스플라인에 제어점이 두 개 이상 필요합니다';return}let curve=makeSpline(splineDraft);checkpoint();objects.push(curve);setTool('spline');$('#status').textContent='스플라인을 만들었습니다'}
function isNumericTool(){return ['line','polyline','spline','rect','ellipse','circle','dimension','measure','move','copy','wall','door','window','wire','resistor','capacitor','inductor','voltage','pcbboard','pcbtrace'].includes(tool)}
function numericPoint(p){if(numericEntry===null)return p;let text=numericEntry.trim();if(tool==='rect'||tool==='ellipse'||tool==='pcbboard'){let parts=text.split(',');if(parts.length>2||parts.some(x=>!/^\d+(?:\.\d*)?$/.test(x)))return null;let w=Number(parts[0]),h=parts.length===2?Number(parts[1]):w;if(!(w>0&&h>0))return null;return {x:start.x+(p.x<start.x?-w:w),y:start.y+(p.y<start.y?-h:h)}}let parts=text.split('<');if(parts.length>2||!/^\d+(?:\.\d*)?$/.test(parts[0])||Number(parts[0])<=0)return null;let dx=p.x-start.x,dy=p.y-start.y,angle=Math.atan2(dy,dx);if(parts.length===2){if(!/^-?\d+(?:\.\d*)?$/.test(parts[1])||tool==='circle')return null;angle=Number(parts[1])*Math.PI/180}return {x:start.x+Number(parts[0])*Math.cos(angle),y:start.y+Number(parts[0])*Math.sin(angle)}}
function numericPreview(){if(numericEntry===null)return;let caption=(tool==='rect'||tool==='ellipse'||tool==='pcbboard')?'가로,세로':'길이 (선은 길이<각도 가능)';$('#numericEntry').hidden=false;$('#numericEntry').textContent=caption+': '+numericEntry+'  ↵';if(lastPointer&&start){let p=pt({...lastPointer,shiftKey:shiftHeld}),q=numericPoint(p);if(q)updatePreview(q)}}
function translated(o,dx,dy){let copy=clone(o);MachinaWall.map(copy,p=>({x:p.x+dx,y:p.y+dy}));MachinaSchematic.mapPins(copy,p=>({x:p.x+dx,y:p.y+dy}));if(copy.type==='block'){copy.children=copy.children.map(c=>translated(c,dx,dy));return updateBlockBounds(copy)}for(let q of [copy.a,copy.b,...(copy.kind==='angular'?[copy.vertex]:[]),...(copy.type==='spline'?copy.points:copy.type==='polyline'?copy.vertices:copy.type==='hatch'?copy.loops.flat():[])]){q.x+=dx;q.y+=dy}if(copy.type==='hatch'){MachinaHatch.mapCurves(copy,p=>({x:p.x+dx,y:p.y+dy}),v=>({...v}));if(copy.pattern)for(const line of copy.pattern.lines){line.base.x+=dx;line.base.y+=dy}updateHatchBounds(copy)}return copy}
function finishTransform(p){let dx=p.x-start.x,dy=p.y-start.y,ids=selectionIndices().filter(i=>editable(objects[i]));if(!ids.length)return;checkpoint();let added=[];for(let i of ids){let o=translated(objects[i],dx,dy);if(tool==='copy'){objects.push(o);added.push(objects.length-1)}else objects[i]=o}if(added.length){selectedMany=new Set(added);selected=added.at(-1)}start=null;preview=null;previewMany=[];clearNumeric();$('#status').textContent=tool==='copy'?'복사했습니다':'이동했습니다';render()}
function finishDrawing(p){if(globalThis.MachinaEditors&&!MachinaEditors.allowedTool(tool))return;if(!editable({layer:activeLayer})){$('#status').textContent='현재 레이어가 잠겨 있거나 숨겨져 있습니다';return}let distance=Math.hypot(p.x-start.x,p.y-start.y);if(tool==='measure'){clearNumeric();start=null;preview=null;render();$('#status').textContent='측정 거리: '+distance.toFixed(3)+' mm';return}if(distance>0){if(['wall','door','window','wire','resistor','capacitor','inductor','voltage','pcbboard','pcbtrace'].includes(tool)){let w=Number($('#wallWidth').value);if(tool==='wall'&&(!Number.isFinite(w)||w<=0)){alert('벽 두께에 0보다 큰 수를 입력하세요.');return}let built=MachinaSymbols.build(tool,start,p,w),wallObject;if(tool==='wall'){try{wallObject=MachinaWall.build(start,p,w,activeLayer)}catch(err){alert(err.message);return}}checkpoint();if(tool==='wall')objects.push(wallObject);else if(['pcbboard','pcbtrace'].includes(tool)){const o=MachinaPCB.build(tool,start,p,activeLayer);if(tool==='pcbtrace'&&globalThis.MachinaEditors)Object.assign(o.pcb,MachinaEditors.traceSettings(start));objects.push(o)}else if(['wire','resistor','capacitor','inductor','voltage'].includes(tool))objects.push(MachinaSchematic.build(tool,start,p,objects,activeLayer));else objects.push(...built.map(o=>({...o,layer:activeLayer})))}else if(tool==='ellipse'){let e=ellipseFromBounds(start,p);if(!e){$('#status').textContent='가로와 세로 길이는 0보다 커야 합니다';return}checkpoint();objects.push({...e,layer:activeLayer})}else{checkpoint();objects.push({type:tool==='polyline'?'line':tool,a:start,b:p,layer:activeLayer})}}clearNumeric();if((tool==='polyline'||tool==='pcbtrace'&&globalThis.MachinaEditors?.kind()==='pcb')&&distance>0){start=p;preview=null;$('#status').textContent='다음 점을 클릭하세요 · Enter로 완료';render();return}start=null;preview=null;setTool(tool)}
canvas.addEventListener('pointerdown',e=>{canvas.setPointerCapture(e.pointerId);lastPointer={clientX:e.clientX,clientY:e.clientY};shiftHeld=!!e.shiftKey;let p=pt(e),raw=pt(e,false);if(space||e.button===1){pan={x:e.clientX,y:e.clientY,ox:origin.x,oy:origin.y};return}if(e.button!==0)return;if(tool==='mtext'){if(!editable({layer:activeLayer})){$('#status').textContent='현재 레이어가 잠겨 있거나 숨겨져 있습니다';return}openMText(p);return}if(tool==='select'&&selected>=0&&selectionIndices().length===1&&objects[selected]?.type==='spline'&&editable(objects[selected])&&!(objects[selected].flags&2)){let cps=objects[selected].points,idx=-1,best=9/scale;for(let i=0;i<cps.length;i++){let d=Math.hypot(raw.x-cps[i].x,raw.y-cps[i].y);if(d<best){best=d;idx=i}}if(idx>=0){controlDrag={index:idx,original:clone(objects[selected]),moved:false};$('#status').textContent='스플라인 제어점을 이동하세요';return}}if(tool==='polyline'){let q=numericPoint(p);if(!q){$('#status').textContent='올바른 길이를 입력하세요';return}appendPolylinePoint(q);return}if(tool==='spline'){let q=numericPoint(p);if(!q){$('#status').textContent='올바른 길이를 입력하세요';return}appendSplinePoint(q);return}if(tool==='text'){if(!editable({layer:activeLayer})){$('#status').textContent='현재 레이어가 잠겨 있거나 숨겨져 있습니다';return}let value=prompt('한 줄 문자를 입력하세요','');if(value===null)return;if(!value||value.length>200||/[\x00-\x1f]/.test(value)){alert('문자는 1~200자의 한 줄로 입력하세요.');return}let h=prompt('문자 높이 (mm)','5');if(h===null)return;let height=Number(h);if(!Number.isFinite(height)||height<=0){alert('높이는 0보다 커야 합니다.');return}checkpoint();objects.push({type:'text',a:p,b:{x:p.x+Math.max(height*.6*[...value].length,.01),y:p.y+height},value,height,rotation:0,layer:activeLayer});render();return}if(tool==='arc3'){if(!editable({layer:activeLayer})){$('#status').textContent='현재 레이어가 잠겨 있거나 숨겨져 있습니다';return}if(!start){start=p;arcMid=null;$('#status').textContent='호가 지나는 두 번째 점을 클릭하세요'}else if(!arcMid){if(Math.hypot(p.x-start.x,p.y-start.y)<1e-9)return;arcMid=p;$('#status').textContent='호의 끝점을 클릭하세요'}else{let arc=arcThrough(start,arcMid,p);if(!arc){$('#status').textContent='세 점이 일직선입니다. 다른 끝점을 선택하세요';return}checkpoint();objects.push(arc);setTool('arc3')}return}if(tool==='ground'||tool==='pcbpad'){if(!editable({layer:activeLayer})){$('#status').textContent='현재 레이어가 잠겨 있거나 숨겨져 있습니다';return}checkpoint();if(tool==='ground')objects.push(MachinaSchematic.build(tool,p,null,objects,activeLayer));else objects.push(MachinaPCB.build(tool,p,null,activeLayer));$('#status').textContent=tool==='ground'?'접지 기호를 배치했습니다':'PCB 패드 기호를 배치했습니다';render();return}if(tool==='trim'){trimAt(raw);return}if(tool==='extend'){extendAt(raw);return}if(tool==='offset'){offsetAt(raw);return}if(tool==='move'||tool==='copy'){if(selected<0){for(let i=objects.length-1;i>=0;i--)if(editable(objects[i])&&hit(raw,objects[i])){selected=i;break}if(selected<0){$('#status').textContent='먼저 이동 또는 복사할 객체를 선택하세요';return}$('#status').textContent='기준점을 클릭하세요';render();return}if(!start){start=p;$('#status').textContent='이동할 위치를 클릭하세요 · Shift: 직교';return}let q=numericPoint(p);if(!q){$('#status').textContent='올바른 이동 거리를 입력하세요';return}finishTransform(q);return}if(tool==='select'){normalizeSelection();let found=-1;for(let i=objects.length-1;i>=0;i--)if(editable(objects[i])&&hit(raw,objects[i])){found=i;break}if(e.shiftKey){if(found>=0){if(selectedMany.has(found)){selectedMany.delete(found);selected=selectedMany.size?[...selectedMany].at(-1):-1;drag=null}else{selectedMany.add(found);selected=found}}else selectionBox={a:raw,b:raw,additive:true}}else if(found<0){selected=-1;selectedMany.clear();selectionBox={a:raw,b:raw,additive:false}}else if(!selectedMany.has(found)){selectedMany.clear();selectedMany.add(found);selected=found}else selected=found;if(found>=0&&selectedMany.has(found)){drag={p,originals:selectionIndices().map(i=>({i,o:clone(objects[i])})),moved:false}}render();return}if(!start){start=p;clearNumeric();$('#status').textContent='끝점을 클릭하거나 수치를 입력하고 Enter';$('#hint').style.display='none'}else{let q=numericPoint(p);if(!q){$('#status').textContent='올바른 수치를 입력하세요';return}finishDrawing(q)}});
canvas.addEventListener('pointermove',e=>{lastPointer={clientX:e.clientX,clientY:e.clientY};shiftHeld=!!e.shiftKey;let raw=pt(e,false),p=pt(e);$('#coords').textContent=`X ${raw.x.toFixed(2)}　 Y ${raw.y.toFixed(2)}`;if(selectionBox){selectionBox.b=raw;render();return}if(controlDrag){if(!controlDrag.moved&&Math.hypot(p.x-controlDrag.original.points[controlDrag.index].x,p.y-controlDrag.original.points[controlDrag.index].y)>1e-9){checkpoint();controlDrag.moved=true}if(controlDrag.moved){let o=clone(controlDrag.original);o.points[controlDrag.index]={...p};o.a=MachinaSpline.point(o,o.knots[o.degree]);o.b=MachinaSpline.point(o,o.knots[o.points.length]);objects[selected]=o;render()}return}if(pan){origin={x:pan.ox+e.clientX-pan.x,y:pan.oy+e.clientY-pan.y};render();return}if(drag){let dx=p.x-drag.p.x,dy=p.y-drag.p.y;if((dx||dy)&&!drag.moved){checkpoint();drag.moved=true}if(drag.moved){for(const {i,o} of drag.originals)objects[i]=translated(o,dx,dy);render()}return}if((tool==='spline'||tool==='polyline')&&start){let q=numericPoint(p);if(q)updatePreview(q)}else if(tool==='arc3'&&start){preview=arcMid?arcThrough(start,arcMid,p):{type:'line',a:start,b:p};render()}else if(start){let q=numericPoint(p);if(q)updatePreview(q)}else render()});canvas.addEventListener('pointerleave',()=>{snapMarker=null;$('#snapInfo').textContent='';render()});function updatePreview(p){if(!start)return;$('#liveMeasure').textContent=['line','polyline','measure','dimension','wall','door','window','wire','resistor','capacitor','inductor','voltage','pcbtrace'].includes(tool)?'길이  '+Math.hypot(p.x-start.x,p.y-start.y).toFixed(2)+' mm':'';if((tool==='move'||tool==='copy')&&selected>=0){let dx=p.x-start.x,dy=p.y-start.y;previewMany=selectionIndices().map(i=>translated(objects[i],dx,dy));preview=null}else if(tool==='polyline'){let points=[...polylineDraft,p];preview=points.length>=2&&MachinaPolyline.valid({vertices:points,closed:false})?makePolyline(points):{type:'line',a:start,b:p}}else if(tool==='spline'){let points=[...splineDraft,p];preview=points.length>=2?makeSpline(points):null}else if(tool==='ellipse')preview=ellipseFromBounds(start,p)||{type:'line',a:start,b:p};else preview={type:tool==='measure'?'dimension':tool==='polyline'||['wall','door','window','wire','resistor','capacitor','inductor','voltage','pcbtrace'].includes(tool)?'line':tool==='pcbboard'?'rect':tool,a:start,b:p};render()}
function refreshModifierPreview(){if(start&&lastPointer){let p=pt({...lastPointer,shiftKey:shiftHeld}),q=numericPoint(p);if(!q)return;if(tool==='arc3'){preview=arcMid?arcThrough(start,arcMid,q):{type:'line',a:start,b:q};render()}else updatePreview(q)}}
canvas.addEventListener('pointerup',()=>{if(selectionBox)finishBox();pan=null;drag=null;controlDrag=null});canvas.addEventListener('wheel',e=>{e.preventDefault();let r=canvas.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top,p=world(x,y,false);scale=Math.max(.1,Math.min(8,scale*(e.deltaY<0?1.15:1/1.15)));origin={x:x-p.x*scale,y:y+p.y*scale};render()},{passive:false});
$('#addLayer').onclick=()=>{if(blockEditStack.length){alert('레이어 변경은 블록 편집을 완료한 뒤 진행하세요.');return}let name=prompt('새 레이어 이름','');if(name===null)return;name=name.trim();if(!name||name.length>80||/[<>\\/:;?*|=\x00-\x1f]/.test(name)){alert('올바른 레이어 이름을 입력하세요.');return}if(layers.some(l=>l.name.toLowerCase()===name.toLowerCase())){alert('이미 있는 레이어 이름입니다.');return}checkpoint();layers.push({name,visible:true,locked:false});activeLayer=name;render()};$('#layerList').onclick=e=>{let b=e.target.closest('[data-layer-action]');if(!b)return;let i=Number(b.dataset.index),layer=layers[i];if(!layer)return;let action=b.dataset.layerAction;if(blockEditStack.length&&action!=='select'){alert('레이어 변경은 블록 편집을 완료한 뒤 진행하세요.');return}if(action==='rename'){if(layer.name==='0'){alert('기본 레이어 이름은 변경할 수 없습니다.');return}let name=prompt('새 레이어 이름',layer.name);if(name===null)return;name=name.trim();if(!name||name.length>80||/[<>\\/:;?*|=\x00-\x1f]/.test(name)||layers.some((l,j)=>j!==i&&l.name.toLowerCase()===name.toLowerCase())){alert('유효하고 중복되지 않는 레이어 이름을 입력하세요.');return}let old=layer.name;checkpoint();layer.name=name;walkObjects(objects,o=>{if((o.layer||'0')===old)o.layer=name});if(activeLayer===old)activeLayer=name;render();return}if(action==='select'){if(!layer.visible||layer.locked){$('#status').textContent='숨겨졌거나 잠긴 레이어는 현재 레이어로 선택할 수 없습니다';return}activeLayer=layer.name;render();return}if(action==='delete'){if(layer.name==='0'||hasLayer(layer.name)){alert('기본 레이어 또는 객체가 있는 레이어는 삭제할 수 없습니다.');return}checkpoint();layers.splice(i,1);if(activeLayer===layer.name)activeLayer='0'}else if(action==='visibility'||action==='lock'){checkpoint();let key=action==='visibility'?'visible':'locked';layer[key]=!layer[key];selectedMany=new Set(selectionIndices().filter(j=>editable(objects[j])));if(selected>=0&&!selectedMany.has(selected))selected=selectedMany.size?[...selectedMany].at(-1):-1;if(activeLayer===layer.name&&!editable({layer:activeLayer}))activeLayer='0'}render()};
document.querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>setTool(b.dataset.tool));$('#undo').onclick=()=>history(true);$('#redo').onclick=()=>history(false);function remove(){let ids=selectionIndices().filter(i=>editable(objects[i]));if(ids.length){checkpoint();ids.sort((a,b)=>b-a).forEach(i=>objects.splice(i,1));selected=-1;selectedMany.clear();render()}}$('#remove').onclick=remove;$('#duplicate').onclick=()=>{let ids=selectionIndices().filter(i=>editable(objects[i]));if(!ids.length)return;checkpoint();let added=[];for(let i of ids){let o=clone(objects[i]);objects.push(translated(o,10,10));added.push(objects.length-1)}selectedMany=new Set(added);selected=added.at(-1);render()};function selectionCenter(ids){let boxes=ids.map(i=>objectBounds(objects[i]));return {x:(Math.min(...boxes.map(b=>b.minX))+Math.max(...boxes.map(b=>b.maxX)))/2,y:(Math.min(...boxes.map(b=>b.minY))+Math.max(...boxes.map(b=>b.maxY)))/2}}
function scaleEntity(o,center,factor){MachinaWall.map(o,p=>({x:center.x+(p.x-center.x)*factor,y:center.y+(p.y-center.y)*factor}),factor);if(o.pcb?.kind==='trace')o.pcb.width*=factor;if(o.pcb?.kind==='pad')o.pcb.drill*=factor;MachinaSchematic.mapPins(o,p=>({x:center.x+(p.x-center.x)*factor,y:center.y+(p.y-center.y)*factor}));if(o.type==='block'){o.children.forEach(c=>scaleEntity(c,center,factor));updateBlockBounds(o);return}for(let p of [o.a,o.b,...(o.kind==='angular'?[o.vertex]:[]),...(o.type==='spline'?o.points:o.type==='polyline'?o.vertices:o.type==='hatch'?o.loops.flat():[])]){p.x=center.x+(p.x-center.x)*factor;p.y=center.y+(p.y-center.y)*factor}if(o.type==='hatch'){MachinaHatch.mapCurves(o,p=>({x:center.x+(p.x-center.x)*factor,y:center.y+(p.y-center.y)*factor}),v=>({x:v.x*factor,y:v.y*factor}));if(o.pattern)for(const l of o.pattern.lines){l.base.x=center.x+(l.base.x-center.x)*factor;l.base.y=center.y+(l.base.y-center.y)*factor;l.offset.x*=factor;l.offset.y*=factor;if(l.dashes)l.dashes=l.dashes.map(d=>d*factor)}updateHatchBounds(o)}if(o.kind==='angular')o.arcRadius*=factor;if(o.type==='dimension')o.offset=(o.offset||0)*factor;if(o.type==='text'||o.type==='mtext'){o.height*=factor;if(o.type==='mtext')o.width*=factor}}
function rotateEntity(o,center){MachinaWall.map(o,p=>({x:center.x-(p.y-center.y),y:center.y+(p.x-center.x)}));MachinaSchematic.mapPins(o,p=>({x:center.x-(p.y-center.y),y:center.y+(p.x-center.x)}));if(o.type==='block'){o.children.forEach(c=>rotateEntity(c,center));updateBlockBounds(o);return}if(o.type==='text'||o.type==='mtext'){let w=o.b.x-o.a.x,h=o.b.y-o.a.y,x=o.a.x-center.x,y=o.a.y-center.y;o.a={x:center.x-y,y:center.y+x};o.b={x:o.a.x+w,y:o.a.y+h};o.rotation=(o.rotation||0)+90;return}for(let p of [o.a,o.b,...(o.kind==='angular'?[o.vertex]:[]),...(o.type==='spline'?o.points:o.type==='polyline'?o.vertices:o.type==='hatch'?o.loops.flat():[])]){let x=p.x-center.x,y=p.y-center.y;p.x=center.x-y;p.y=center.y+x}if(o.type==='dimension'&&o.angle!==undefined)o.angle+=90;if(o.type==='arc'){o.startAngle+=90;o.endAngle+=90}if(o.type==='hatch'){MachinaHatch.mapCurves(o,p=>({x:center.x-(p.y-center.y),y:center.y+(p.x-center.x)}),v=>({x:-v.y,y:v.x}));if(o.pattern)for(const l of o.pattern.lines){let x=l.base.x-center.x,y=l.base.y-center.y;l.base={x:center.x-y,y:center.y+x};let ox=l.offset.x;l.offset.x=-l.offset.y;l.offset.y=ox;l.angle+=90}updateHatchBounds(o)}}
function hasText(o){return ['text','mtext'].includes(o.type)||(o.type==='block'&&o.children.some(hasText))}function mirrorEntity(o,cx){MachinaWall.map(o,p=>({x:2*cx-p.x,y:p.y}),1,true);MachinaSchematic.mapPins(o,p=>({x:2*cx-p.x,y:p.y}));if(o.type==='block'){o.children.forEach(c=>mirrorEntity(c,cx));updateBlockBounds(o);return}for(let p of [o.a,o.b,...(o.kind==='angular'?[o.vertex]:[]),...(o.type==='spline'?o.points:o.type==='polyline'?o.vertices:o.type==='hatch'?o.loops.flat():[])])p.x=2*cx-p.x;if(o.type==='dimension'){if(o.kind==='angular')[o.a,o.b]=[o.b,o.a];o.offset=-(o.offset||0);if(o.angle!==undefined)o.angle=180-o.angle}if(o.type==='arc'){let a=o.startAngle;o.startAngle=180-o.endAngle;o.endAngle=180-a}if(o.type==='ellipse'&&!ellipseIsFull(o)){let t=o.startParam;o.startParam=-o.endParam;o.endParam=-t}if(o.type==='polyline')for(const v of o.vertices)v.bulge=-(v.bulge||0);if(o.type==='hatch'){MachinaHatch.mapCurves(o,p=>({x:2*cx-p.x,y:p.y}),v=>({x:-v.x,y:v.y}));for(const v of o.loops.flat())v.bulge=-(v.bulge||0);if(o.pattern)for(const l of o.pattern.lines){l.base.x=2*cx-l.base.x;l.offset.x=-l.offset.x;l.angle=180-l.angle}updateHatchBounds(o)}}
function updateHatchBounds(o){let b=MachinaHatch.bounds(o);o.a=b.a;o.b=b.b;return o}
function createHatch(patterned=false,doubled=false){if(selectionIndices().length!==1||selected<0){$('#status').textContent='닫힌 폴리라인·스플라인, 사각형, 원 또는 전체 타원 하나를 선택하세요';return}let source=objects[selected],loop;if(source.type==='polyline'&&source.closed)loop=clone(source.vertices);else if(source.type==='rect'){let a=source.a,b=source.b;loop=[{x:a.x,y:a.y,bulge:0},{x:b.x,y:a.y,bulge:0},{x:b.x,y:b.y,bulge:0},{x:a.x,y:b.y,bulge:0}]}else if(source.type==='ellipse'&&ellipseIsFull(source)){let ux=source.b.x-source.a.x,uy=source.b.y-source.a.y,c={type:'ellipse',cx:source.a.x,cy:source.a.y,ux,uy,vx:-uy*source.ratio,vy:ux*source.ratio,start:0,sweep:Math.PI/2};loop=Array.from({length:4},(_,i)=>{let curve={...c,start:i*Math.PI/2},t=curve.start;return {x:c.cx+c.ux*Math.cos(t)+c.vx*Math.sin(t),y:c.cy+c.uy*Math.cos(t)+c.vy*Math.sin(t),bulge:0,curve}})}else if(source.type==='spline'&&Math.hypot(source.a.x-source.b.x,source.a.y-source.b.y)<1e-8){let c=clone(source);c.type='spline';c.periodic=(c.flags&2)?1:0;c.start=c.knots[c.degree];c.sweep=c.knots[c.points.length]-c.start;loop=[{x:source.a.x,y:source.a.y,bulge:0,curve:c}]}else if(source.type==='circle'){let r=Math.hypot(source.b.x-source.a.x,source.b.y-source.a.y);loop=[{x:source.a.x+r,y:source.a.y,bulge:1},{x:source.a.x-r,y:source.a.y,bulge:1}]}else{$('#status').textContent='닫힌 폴리라인·스플라인, 사각형, 원 또는 전체 타원 하나만 채울 수 있습니다';return}let o={type:'hatch',loops:[loop],layer:source.layer||'0'};if(patterned)o.pattern={name:doubled?'USER':'ANSI31',...(doubled?{patternType:0,double:true}:{}),lines:[{angle:45,base:{x:loop[0].x,y:loop[0].y},offset:{x:-2.2450640303,y:2.2450640303}}]};if(!MachinaHatch.valid(o)){alert('닫힌 경계를 확인하세요.');return}updateHatchBounds(o);if(o.pattern){try{MachinaHatch.patternSegments(o)}catch{alert('해치 패턴이 너무 촘촘합니다.');return}}checkpoint();let i=selected;objects.splice(i,0,o);selected=i;selectedMany=new Set([i]);$('#status').textContent=patterned?'독립 선 패턴 해치를 만들었습니다':'독립 단색 해치를 만들었습니다';render()}
