$('#createBlock').onclick=()=>{let ids=selectionIndices().filter(i=>editable(objects[i]));if(!ids.length){$('#status').textContent='블록으로 묶을 객체를 먼저 선택하세요';return}if(!editable({layer:'0'})){alert('기본 레이어를 보이고 잠금 해제하세요.');return}let name=prompt('블록 이름','BLOCK');if(name===null)return;name=name.trim();if(!name||name.length>80||/[\x00-\x1f]/.test(name)){alert('올바른 블록 이름을 입력하세요.');return}checkpoint();let children=ids.map(i=>clone(objects[i]));ids.sort((a,b)=>b-a).forEach(i=>objects.splice(i,1));objects.push(makeBlock(name,children));selected=objects.length-1;selectedMany=new Set([selected]);render()};$('#explodeBlock').onclick=()=>{if(selectionIndices().length!==1||selected<0||objects[selected].type!=='block'){$('#status').textContent='분해할 블록 하나를 선택하세요';return}if(!editable(objects[selected])){$('#status').textContent='잠겼거나 숨겨진 내부 레이어가 있습니다';return}if(objects[selected].electrical&&!confirm('분해하면 이 부품의 핀·값·회로 연결 정보가 사라집니다. 계속하시겠습니까?'))return;checkpoint();let i=selected,children=clone(objects[i].children);objects.splice(i,1,...children);selectedMany=new Set(children.map((_,j)=>i+j));selected=children.length?i+children.length-1:-1;render()};
